[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nine Decades of Oscar-Winning Scores: A Historical Trend Analysis (1934–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  /* ===== RESET & BASE ===== */
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  :root {
    --gold:       #C9A84C;
    --gold-light: #F0D27A;
    --gold-pale:  #FDF6E3;
    --dark:       #1A1A2E;
    --dark2:      #16213E;
    --mid:        #0F3460;
    --accent:     #E94560;
    --text:       #2D2D2D;
    --text-light: #5A5A6A;
    --bg:         #FAFAF8;
    --card-bg:    #FFFFFF;
    --border:     #E8E4D9;
    --success:    #2E7D32;
    --font-head:  'Georgia', 'Times New Roman', serif;
    --font-body:  'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
    --shadow:     0 2px 12px rgba(0,0,0,0.08);
    --shadow-md:  0 4px 24px rgba(0,0,0,0.12);
  }
  html { scroll-behavior: smooth; font-size: 16px; }
  body {
    font-family: var(--font-body);
    background: var(--bg);
    color: var(--text);
    line-height: 1.7;
  }

  /* ===== HERO HEADER ===== */
  .hero {
    background: linear-gradient(135deg, var(--dark) 0%, var(--dark2) 40%, var(--mid) 100%);
    color: white;
    padding: 80px 40px 60px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .hero::before {
    content: '';
    position: absolute; inset: 0;
    background: repeating-linear-gradient(
      45deg,
      transparent,
      transparent 80px,
      rgba(201,168,76,0.04) 80px,
      rgba(201,168,76,0.04) 81px
    );
  }
  .hero-oscar {
    font-size: 3rem;
    margin-bottom: 16px;
    display: block;
  }
  .hero h1 {
    font-family: var(--font-head);
    font-size: clamp(1.8rem, 4vw, 3rem);
    font-weight: 700;
    letter-spacing: -0.5px;
    line-height: 1.2;
    margin-bottom: 14px;
    color: var(--gold-light);
  }
  .hero .subtitle {
    font-size: 1.1rem;
    color: rgba(255,255,255,0.75);
    max-width: 680px;
    margin: 0 auto 28px;
  }
  .hero-meta {
    display: flex;
    gap: 32px;
    justify-content: center;
    flex-wrap: wrap;
    font-size: 0.85rem;
    color: rgba(255,255,255,0.55);
    border-top: 1px solid rgba(255,255,255,0.12);
    padding-top: 20px;
    margin-top: 8px;
  }
  .hero-meta span { display: flex; align-items: center; gap: 6px; }

  /* ===== NAV ===== */
  .toc-nav {
    background: var(--dark);
    padding: 0 40px;
    position: sticky;
    top: 0;
    z-index: 100;
    border-bottom: 2px solid var(--gold);
  }
  .toc-nav ul {
    list-style: none;
    display: flex;
    gap: 0;
    overflow-x: auto;
    scrollbar-width: none;
  }
  .toc-nav ul::-webkit-scrollbar { display: none; }
  .toc-nav a {
    display: block;
    padding: 14px 16px;
    color: rgba(255,255,255,0.65);
    text-decoration: none;
    font-size: 0.82rem;
    font-weight: 500;
    letter-spacing: 0.3px;
    white-space: nowrap;
    border-bottom: 3px solid transparent;
    transition: all 0.2s;
  }
  .toc-nav a:hover { color: var(--gold-light); border-bottom-color: var(--gold); }

  /* ===== LAYOUT ===== */
  .container { max-width: 1100px; margin: 0 auto; padding: 0 32px; }
  .section { padding: 64px 0; border-bottom: 1px solid var(--border); }
  .section:last-child { border-bottom: none; }
  .section-label {
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 2.5px;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 8px;
  }
  .section-title {
    font-family: var(--font-head);
    font-size: clamp(1.5rem, 3vw, 2.2rem);
    color: var(--dark);
    margin-bottom: 20px;
    line-height: 1.2;
  }
  .section-intro {
    font-size: 1.05rem;
    color: var(--text-light);
    max-width: 780px;
    margin-bottom: 40px;
    line-height: 1.8;
  }

  /* ===== KPI CARDS ===== */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 20px;
    margin-bottom: 40px;
  }
  .kpi-card {
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-top: 4px solid var(--gold);
    border-radius: 12px;
    padding: 28px 24px;
    box-shadow: var(--shadow);
    transition: transform 0.2s, box-shadow 0.2s;
  }
  .kpi-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
  .kpi-label {
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--text-light);
    margin-bottom: 10px;
  }
  .kpi-value {
    font-family: var(--font-head);
    font-size: 3rem;
    font-weight: 700;
    color: var(--dark);
    line-height: 1;
    margin-bottom: 8px;
  }
  .kpi-desc {
    font-size: 0.85rem;
    color: var(--text-light);
    line-height: 1.5;
  }
  .kpi-badge {
    display: inline-block;
    background: var(--gold-pale);
    color: #7A5C00;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.5px;
    padding: 3px 10px;
    border-radius: 20px;
    margin-top: 6px;
  }

  /* ===== CHARTS ===== */
  .chart-wrap {
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 28px 24px;
    box-shadow: var(--shadow);
    margin-bottom: 32px;
  }
  .chart-title {
    font-family: var(--font-head);
    font-size: 1.05rem;
    font-weight: 700;
    color: var(--dark);
    margin-bottom: 4px;
  }
  .chart-subtitle {
    font-size: 0.82rem;
    color: var(--text-light);
    margin-bottom: 20px;
  }
  .chart-container { position: relative; }

  /* ===== TWO-COL ===== */
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
  @media (max-width: 768px) { .two-col { grid-template-columns: 1fr; } }

  /* ===== COMPOSER RANKING ===== */
  .composer-rank {
    list-style: none;
  }
  .composer-rank-item {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 14px 16px;
    border-radius: 8px;
    margin-bottom: 6px;
    background: var(--card-bg);
    border: 1px solid var(--border);
    transition: background 0.15s;
  }
  .composer-rank-item:hover { background: var(--gold-pale); }
  .rank-num {
    font-family: var(--font-head);
    font-size: 1.1rem;
    font-weight: 700;
    color: var(--gold);
    width: 28px;
    text-align: center;
    flex-shrink: 0;
  }
  .rank-num.top3 { color: var(--accent); font-size: 1.3rem; }
  .rank-name {
    flex: 1;
    font-weight: 600;
    font-size: 0.95rem;
    color: var(--dark);
  }
  .rank-films {
    font-size: 0.78rem;
    color: var(--text-light);
    margin-top: 2px;
    font-style: italic;
  }
  .rank-bar-wrap {
    flex: 0 0 120px;
    display: flex;
    align-items: center;
    gap: 10px;
  }
  .rank-bar {
    height: 8px;
    background: linear-gradient(90deg, var(--gold), var(--gold-light));
    border-radius: 4px;
    transition: width 0.4s;
  }
  .rank-count {
    font-weight: 700;
    font-size: 1rem;
    color: var(--dark);
    min-width: 14px;
    text-align: right;
  }

  /* ===== ERA CARDS ===== */
  .era-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; margin-bottom: 32px; }
  .era-card {
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 28px 22px;
    box-shadow: var(--shadow);
    position: relative;
    overflow: hidden;
  }
  .era-card::before {
    content: '';
    position: absolute; top: 0; left: 0; right: 0; height: 4px;
  }
  .era-card.golden::before  { background: linear-gradient(90deg, #C9A84C, #F0D27A); }
  .era-card.silver::before  { background: linear-gradient(90deg, #7F8C8D, #BDC3C7); }
  .era-card.modern::before  { background: linear-gradient(90deg, #2980B9, #6DD5FA); }
  .era-card.contemp::before { background: linear-gradient(90deg, #8E44AD, #C39BD3); }
  .era-name {
    font-family: var(--font-head);
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--dark);
    margin-bottom: 4px;
  }
  .era-years { font-size: 0.78rem; font-weight: 600; color: var(--text-light); letter-spacing: 0.5px; margin-bottom: 12px; }
  .era-stat { display: flex; justify-content: space-between; margin-bottom: 8px; }
  .era-stat-label { font-size: 0.82rem; color: var(--text-light); }
  .era-stat-value { font-size: 0.9rem; font-weight: 700; color: var(--dark); }
  .era-composers {
    margin-top: 14px;
    padding-top: 14px;
    border-top: 1px solid var(--border);
    font-size: 0.8rem;
    color: var(--text-light);
    line-height: 1.6;
  }
  .era-composers strong { color: var(--dark); }

  /* ===== TIMELINE / DECADE TABLE ===== */
  .decade-block {
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 10px;
    margin-bottom: 20px;
    overflow: hidden;
    box-shadow: var(--shadow);
  }
  .decade-header {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 16px 24px;
    background: linear-gradient(90deg, var(--dark) 0%, var(--dark2) 100%);
    cursor: pointer;
    user-select: none;
  }
  .decade-header:hover { background: linear-gradient(90deg, var(--mid) 0%, var(--dark2) 100%); }
  .decade-label {
    font-family: var(--font-head);
    font-size: 1.1rem;
    font-weight: 700;
    color: var(--gold-light);
  }
  .decade-tag {
    font-size: 0.72rem;
    background: rgba(201,168,76,0.2);
    color: var(--gold-light);
    padding: 3px 10px;
    border-radius: 12px;
    font-weight: 600;
  }
  .decade-arrow {
    margin-left: auto;
    color: rgba(255,255,255,0.4);
    font-size: 0.9rem;
    transition: transform 0.3s;
  }
  .decade-body { overflow: hidden; max-height: 0; transition: max-height 0.4s ease; }
  .decade-body.open { max-height: 2000px; }
  .decade-table { width: 100%; border-collapse: collapse; }
  .decade-table th {
    background: var(--gold-pale);
    color: #6B4C00;
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    padding: 10px 18px;
    text-align: left;
  }
  .decade-table td { padding: 10px 18px; font-size: 0.88rem; border-bottom: 1px solid var(--border); }
  .decade-table tr:last-child td { border-bottom: none; }
  .decade-table tr:hover td { background: #FAFAF0; }
  .repeat-badge {
    display: inline-block;
    background: #FFF3CD;
    color: #856404;
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.3px;
    padding: 1px 7px;
    border-radius: 4px;
    margin-left: 6px;
    vertical-align: middle;
  }

  /* ===== MILESTONE CARDS ===== */
  .milestones-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 18px; }
  .milestone-card {
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 22px 20px;
    box-shadow: var(--shadow);
    display: flex;
    gap: 16px;
  }
  .milestone-icon {
    font-size: 1.8rem;
    flex-shrink: 0;
    line-height: 1;
  }
  .milestone-title {
    font-weight: 700;
    font-size: 0.88rem;
    color: var(--dark);
    margin-bottom: 4px;
    letter-spacing: 0.2px;
  }
  .milestone-detail {
    font-size: 0.82rem;
    color: var(--text-light);
    line-height: 1.5;
  }
  .milestone-highlight { color: var(--dark); font-weight: 600; }

  /* ===== CALLOUT ===== */
  .callout {
    background: linear-gradient(135deg, var(--gold-pale), #FFF8E7);
    border: 1px solid var(--gold);
    border-left: 5px solid var(--gold);
    border-radius: 0 10px 10px 0;
    padding: 20px 24px;
    margin: 28px 0;
    font-size: 0.95rem;
    color: var(--text);
    line-height: 1.7;
  }
  .callout strong { color: var(--dark); }

  /* ===== TAKEAWAYS ===== */
  .takeaway-list { list-style: none; counter-reset: takeaway; }
  .takeaway-item {
    counter-increment: takeaway;
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 22px 22px 22px 72px;
    margin-bottom: 16px;
    position: relative;
    box-shadow: var(--shadow);
    line-height: 1.7;
    font-size: 0.95rem;
  }
  .takeaway-item::before {
    content: counter(takeaway);
    position: absolute;
    left: 22px;
    top: 20px;
    width: 32px;
    height: 32px;
    background: linear-gradient(135deg, var(--gold), var(--gold-light));
    color: var(--dark);
    font-weight: 800;
    font-size: 1rem;
    font-family: var(--font-head);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
  }
  .takeaway-title {
    font-weight: 700;
    color: var(--dark);
    margin-bottom: 6px;
    font-size: 1rem;
  }

  /* ===== WIN TIMELINE BAR ===== */
  .win-timeline {
    display: flex;
    flex-wrap: wrap;
    gap: 3px;
    margin-bottom: 4px;
  }
  .win-dot {
    width: 9px; height: 9px;
    border-radius: 50%;
    background: var(--border);
    title: attr(data-year);
  }
  .win-dot.won { background: var(--gold); }
  .win-dot.won4 { background: var(--accent); }

  /* ===== FULL DATA TABLE ===== */
  .data-table-wrap { overflow-x: auto; }
  .data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.84rem;
  }
  .data-table thead th {
    background: var(--dark);
    color: var(--gold-light);
    padding: 12px 16px;
    text-align: left;
    font-size: 0.75rem;
    letter-spacing: 1px;
    text-transform: uppercase;
    position: sticky;
    top: 0;
  }
  .data-table tbody td {
    padding: 9px 16px;
    border-bottom: 1px solid var(--border);
    vertical-align: middle;
  }
  .data-table tbody tr:hover td { background: var(--gold-pale); }
  .data-table tbody tr.repeat-row td { background: #FFFDF0; }

  /* ===== FOOTER ===== */
  .report-footer {
    background: var(--dark);
    color: rgba(255,255,255,0.45);
    text-align: center;
    padding: 36px 40px;
    font-size: 0.8rem;
    line-height: 1.8;
  }
  .report-footer a { color: rgba(255,255,255,0.6); }

  /* ===== UTILS ===== */
  .text-gold { color: var(--gold); }
  .text-accent { color: var(--accent); }
  .mt-0 { margin-top: 0 !important; }
  .mb-24 { margin-bottom: 24px; }
  .small { font-size: 0.82rem; color: var(--text-light); }

  @media print {
    .toc-nav, .decade-arrow { display: none; }
    .decade-body { max-height: none !important; }
  }
</style>
</head>
<body>

<!-- ============================================================ HERO -->
<header class="hero">
