// ── HELPERS ───────────────────────────────────────────────────────────────
function parseComposers(str) {
  return str.split(',').map(s => s.trim());
}

// Build win counts per individual
const composerWins = {};
DATA.forEach(row => {
  parseComposers(row.composer).forEach(c => {
    if (!composerWins[c]) composerWins[c] = [];
    composerWins[c].push(row.year);
  });
});

// ── FULL DATA TABLE ────────────────────────────────────────────────────────
const tbody = document.getElementById('fullDataBody');
const seenForTable = {};
DATA.forEach((row, i) => {
  const comps = parseComposers(row.composer);
  const winNums = comps.map(c => {
    if (!seenForTable[c]) seenForTable[c] = 0;
    seenForTable[c]++;
    return seenForTable[c] > 1 ? `${c} (win #${seenForTable[c]})` : null;
  }).filter(Boolean);
  const isRepeat = winNums.length > 0;
  const totalWins = Math.max(...comps.map(c => composerWins[c].length));
  const winLabel = totalWins > 1
    ? `<span style="color:var(--gold);font-weight:700">${totalWins}×</span>`
    : '1';
  const tr = document.createElement('tr');
  if (isRepeat) tr.className = 'repeat-row';
  tr.innerHTML = `<td style="color:var(--text-light)">${i+1}</td><td><strong>${row.year}</strong></td><td><em>${row.film}</em></td><td>${row.composer}</td><td>${winLabel}</td>`;
  tbody.appendChild(tr);
});

