// ── DECADE TOGGLE ─────────────────────────────────────────────────────────
function toggleDecade(header) {
  const body = header.nextElementSibling;
  const arrow = header.querySelector('.decade-arrow');
  const isOpen = body.classList.contains('open');
  body.classList.toggle('open', !isOpen);
  arrow.style.transform = isOpen ? '' : 'rotate(180deg)';
}

// Open 2020s by default to highlight most recent data
document.addEventListener('DOMContentLoaded', () => {
  const blocks = document.querySelectorAll('.decade-block');
  const last = blocks[blocks.length - 1];
  if (last) {
    const hdr = last.querySelector('.decade-header');
    if (hdr) toggleDecade(hdr);
  }
});
